@DoNotInline public static AudioOffloadSupport getOffloadedPlaybackSupport(AudioFormat audioFormat, android.media.AudioAttributes audioAttributes, boolean isOffloadVariableRateSupported) {
  int playbackOffloadSupport;
  try {
    playbackOffloadSupport = AudioManager.getPlaybackOffloadSupport(audioFormat, audioAttributes);
  } catch (IllegalArgumentException | NullPointerException e) {
    playbackOffloadSupport = AudioManager.PLAYBACK_OFFLOAD_NOT_SUPPORTED;
  }
  if (playbackOffloadSupport == AudioManager.PLAYBACK_OFFLOAD_NOT_SUPPORTED) {
    return AudioOffloadSupport.DEFAULT_UNSUPPORTED;
  }
  AudioOffloadSupport.Builder audioOffloadSupport = new AudioOffloadSupport.Builder();
  return audioOffloadSupport.setIsFormatSupported(true)
      .setIsGaplessSupported(playbackOffloadSupport == AudioManager.PLAYBACK_OFFLOAD_GAPLESS_SUPPORTED)
      .setIsSpeedChangeSupported(isOffloadVariableRateSupported)
      .build();
}
